/**
 * Lane B evidence verifier (TASK-011; TEST-STRATEGY section 9.2; ADR-0023 amendments B, G, I item 4). Every fixture is a
 * throw-away git repository built at run time (no committed binary fixtures): a base commit, a code change, and an
 * evidence commit whose run directory is generated by `writeRun` and then mutated per negative case.
 */
import { spawnSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import { mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join } from 'node:path';

import { afterAll, describe, expect, it, jest } from '@jest/globals';

import { findRepoRoot, runNode, type RunResult } from '../test-support/process.js';
import { allowedRunFile, nameHasId } from './check-evidence.mjs';
import { parseManifest } from './lib/manifest.mjs';

const repoRoot = findRepoRoot();
const script = join(repoRoot, 'tools', 'quality', 'check-evidence.mjs');
const temps: string[] = [];
afterAll(() => temps.forEach((dir) => rmSync(dir, { recursive: true, force: true })));

const STAMP = '20261113T1000Z';

// Every case builds a git repository and spawns the checker; Windows hosts need more than the 5 s default.
jest.setTimeout(60_000);

function git(cwd: string, args: string[]): string {
  const result = spawnSync(
    'git',
    [
      '-c',
      'core.autocrlf=false',
      '-c',
      'commit.gpgsign=false',
      '-c',
      'user.name=fixture',
      '-c',
      'user.email=fixture@example.invalid',
      ...args,
    ],
    { cwd, encoding: 'utf8', timeout: 30_000, windowsHide: true },
  );
  if (result.status !== 0) throw new Error(`git ${args.join(' ')} failed: ${result.stderr}`);
  return result.stdout.trim();
}

function write(root: string, path: string, content: string): void {
  mkdirSync(dirname(join(root, path)), { recursive: true });
  writeFileSync(join(root, path), content);
}

function commitAll(root: string, message: string): string {
  git(root, ['add', '-A']);
  git(root, ['commit', '-q', '-m', message]);
  return git(root, ['rev-parse', 'HEAD']);
}

const sha256 = (text: string): string => createHash('sha256').update(text).digest('hex');

function suiteSpec(status: string, extra: Record<string, unknown> = {}): Record<string, unknown> {
  return { lane: ['B'], security: false, zero_skip: false, status, min_tests: 1, required_cases: [], ...extra };
}

const MANIFEST = {
  manifest_version: 1,
  rules: {
    invalid_env_prefixes: ['SKIP_'],
    recorded_env_prefixes: ['SKIP_', 'TEST_'],
    clean_tree_paths: ['apps/**', 'tools/**', '*.config.*', '.env*', '!.env.example', 'package*.json'],
  },
  tooling_inputs: ['docs/03-architecture/api/**'],
  deferred_at_gate: [],
  suites: {
    unit: suiteSpec('active'),
    integration: suiteSpec('active'),
    'rbac-matrix': suiteSpec('active', { security: true, zero_skip: true, required_cases: ['SEC-TC-01'] }),
    'e2e-chromium': suiteSpec('planned'),
  },
  profiles: {
    pr: { always: ['unit'] },
    wave: { always: ['unit', 'integration', 'rbac-matrix'] },
    gate: { always: ['unit', 'integration', 'rbac-matrix', 'e2e-chromium'] },
  },
  path_rules: [
    { id: 'backend', globs: ['apps/api/**'], profile_min: 'pr', suites: ['integration', 'rbac-matrix'] },
    { id: 'frontend', globs: ['apps/web/**'], profile_min: 'pr', suites: ['e2e-chromium'] },
    { id: 'docs-or-ci-only', globs: ['docs/**', '.github/**'], exclude: ['docs/03-architecture/api/**'], profile_min: 'none', suites: [] },
  ],
};

type Status = 'passed' | 'failed' | 'error' | 'skipped';
interface Case {
  name: string;
  status: Status;
}
interface RunSpec {
  summary: Record<string, unknown>;
  files: Map<string, string>;
}

function junitXml(suite: string, cases: Case[]): string {
  const count = (s: Status): number => cases.filter((c) => c.status === s).length;
  const totals = `tests="${cases.length}" failures="${count('failed')}" errors="${count('error')}" skipped="${count('skipped')}"`;
  const body = cases.map((c) => {
    const child =
      c.status === 'failed'
        ? '<failure message="x"/>'
        : c.status === 'error'
          ? '<error message="x"/>'
          : c.status === 'skipped'
            ? '<skipped/>'
            : '';
    return `    <testcase name="${c.name}" classname="${suite}" time="0.010">${child}</testcase>`;
  });
  return [
    '<?xml version="1.0" encoding="UTF-8"?>',
    `<testsuites name="${suite}" ${totals}>`,
    `  <testsuite name="${suite}" ${totals}>`,
    ...body,
    '  </testsuite>',
    '</testsuites>',
    '',
  ].join('\n');
}

const DEFAULT_CASES: Record<string, Case[]> = {
  unit: [{ name: 'adds numbers', status: 'passed' }],
  integration: [{ name: 'talks to postgres', status: 'passed' }],
  'rbac-matrix': [
    { name: '[SEC-TC-01] viewer cannot book', status: 'passed' },
    { name: 'owner can book', status: 'passed' },
  ],
};

/** A well-formed run for `gitSha`; `mutate` edits it before it is written and the hashes are computed afterwards. */
function buildRun(gitSha: string, cases: Record<string, Case[]> = DEFAULT_CASES): RunSpec {
  const files = new Map<string, string>();
  for (const [name, list] of Object.entries(cases)) files.set(`${name}.junit.xml`, junitXml(name, list));
  files.set('coverage-summary.json', '{"total":{"lines":{"pct":90}}}\n');
  const suites = Object.entries(cases).map(([name, list]) => {
    const count = (s: Status): number => list.filter((c) => c.status === s).length;
    return {
      name,
      status: count('failed') + count('error') > 0 ? 'failed' : 'passed',
      tests: list.length,
      failures: count('failed'),
      errors: count('error'),
      skipped: count('skipped'),
      duration_s: 1,
      report: `${name}.junit.xml`,
      report_sha256: '',
    };
  });
  return {
    files,
    summary: {
      schema_version: 1,
      lane: 'B',
      profile: 'pr',
      git_sha: gitSha,
      git_dirty: false,
      build_clean: true,
      stamp: STAMP,
      generated_at: '2026-11-13T10:00:00Z',
      host: {
        os: 'fixture',
        cpu_model: 'fixture',
        cores: 4,
        ram_gb: 16,
        docker_version: null,
        node_version: 'v24.11.0',
        npm_version: '11.19.1',
      },
      lockfile_sha256: sha256('lock'),
      manifest_sha256: sha256('manifest'),
      testcontainers_images: [],
      env_overrides: [],
      suites,
      attachments: [{ file: 'coverage-summary.json', sha256: '' }],
      verdict: 'PASS',
      invalid_reasons: [],
    },
  };
}

/** Writes the run directory after filling in the report and attachment hashes; `afterHash` tampers afterwards. */
function writeRun(root: string, run: RunSpec, afterHash: (run: RunSpec) => void = () => undefined): string {
  const gitSha = String(run.summary.git_sha);
  const dir = `docs/05-quality/tests/runs/${STAMP}_${gitSha.slice(0, 7)}`;
  for (const suite of run.summary.suites as { report: string; report_sha256: string }[])
    suite.report_sha256 = sha256(run.files.get(suite.report) ?? '');
  for (const attachment of run.summary.attachments as { file: string; sha256: string }[])
    attachment.sha256 = sha256(run.files.get(attachment.file) ?? '');
  afterHash(run);
  for (const [file, content] of run.files) write(root, `${dir}/${file}`, content);
  write(root, `${dir}/summary.json`, `${JSON.stringify(run.summary, null, 2)}\n`);
  return dir;
}

interface Fixture {
  root: string;
  base: string;
  code: string;
  manifest: string;
}

/** base commit -> code change under apps/api (selects integration + rbac-matrix + unit). */
function fixture(manifest: Record<string, unknown> = MANIFEST): Fixture {
  const root = mkdtempSync(join(tmpdir(), 'evidence-'));
  const side = mkdtempSync(join(tmpdir(), 'evidence-manifest-'));
  temps.push(root, side);
  git(root, ['init', '-q', '-b', 'main']);
  write(root, 'apps/api/src/app.ts', 'export const app = 1;\n');
  write(root, 'docs/03-architecture/api/openapi.yaml', 'openapi: 3.1.0\n');
  write(root, 'docs/README.md', '# docs\n');
  const base = commitAll(root, 'chore: base');
  write(root, 'apps/api/src/app.ts', 'export const app = 2;\n');
  const code = commitAll(root, 'feat: change');
  const manifestFile = join(side, 'required-suites.json');
  writeFileSync(manifestFile, JSON.stringify(manifest));
  return { root, base, code, manifest: manifestFile };
}

function check(f: Fixture, head: string, extra: string[] = []): RunResult {
  return runNode([script, '--root', f.root, '--base', f.base, '--head', head, '--manifest', f.manifest, ...extra], { cwd: repoRoot });
}

/** Fixture + evidence commit; returns the evidence head. */
function withRun(mutate: (run: RunSpec) => void = () => undefined, afterHash?: (run: RunSpec) => void): { f: Fixture; head: string } {
  const f = fixture();
  const run = buildRun(f.code);
  mutate(run);
  writeRun(f.root, run, afterHash);
  const head = commitAll(f.root, `test(evidence): heavy lane pr ${f.code.slice(0, 7)} PASS`);
  return { f, head };
}

const suiteOf = (run: RunSpec, name: string): Record<string, unknown> =>
  (run.summary.suites as Record<string, unknown>[]).find((s) => s.name === name) ?? {};

describe('check-evidence: positive controls', () => {
  it('a well-formed run for the change passes', () => {
    const { f, head } = withRun();
    const result = check(f, head);
    expect(result.stdout).toContain('accepted');
    expect(result.status).toBe(0);
  });

  it('a later docs-only change keeps the evidence fresh (staleness allow-list)', () => {
    const { f } = withRun();
    write(f.root, 'docs/README.md', '# docs v2\n');
    const head = commitAll(f.root, 'docs: edit');
    expect(check(f, head).status).toBe(0);
  });

  it('docs-only change: PASS with an explicit note and no evidence needed', () => {
    const f = fixture();
    write(f.root, 'docs/README.md', '# docs v3\n');
    const head = commitAll(f.root, 'docs: only');
    const result = runNode([script, '--root', f.root, '--base', f.code, '--head', head, '--manifest', f.manifest], { cwd: repoRoot });
    expect(result.status).toBe(0);
    expect(result.stdout).toContain('no active lane B suite is required');
  });

  it('every selected suite still planned: PASS with the planned suites listed', () => {
    const f = fixture({ ...MANIFEST, suites: { ...MANIFEST.suites, unit: suiteSpec('planned') } });
    write(f.root, 'apps/web/page.tsx', 'export {};\n');
    const head = commitAll(f.root, 'feat: web');
    const result = runNode([script, '--root', f.root, '--base', f.code, '--head', head, '--manifest', f.manifest], { cwd: repoRoot });
    expect(result.status).toBe(0);
    expect(result.stdout).toContain('still planned: e2e-chromium, unit');
  });

  it('writes a markdown table to --summary', () => {
    const { f, head } = withRun();
    const summary = join(f.root, '..', `${STAMP}-summary-${Math.random().toString(16).slice(2)}.md`);
    temps.push(summary);
    expect(check(f, head, ['--summary', summary]).status).toBe(0);
    const text = readFileSync(summary, 'utf8');
    expect(text).toContain('| Run | Changed here | Profile |');
    expect(text).toContain('Required (active): integration, rbac-matrix, unit');
  });
});

describe('check-evidence: SEC-TC-48 negative fixtures', () => {
  it('[SEC-TC-48] FAIL on verdict PASS with a JUnit attachment showing failures', () => {
    const { f, head } = withRun((run) => {
      run.files.set(
        'rbac-matrix.junit.xml',
        junitXml('rbac-matrix', [
          { name: '[SEC-TC-01] viewer cannot book', status: 'passed' },
          { name: 'owner can book', status: 'failed' },
        ]),
      );
      Object.assign(suiteOf(run, 'rbac-matrix'), { failures: 1, status: 'passed' });
    });
    const result = check(f, head);
    expect(result.status).toBe(1);
    expect(result.stdout).toContain('declared PASS but the reports say FAIL');
  });

  it('[SEC-TC-48] FAIL on a missing required security suite', () => {
    const { f, head } = withRun((run) => {
      run.files.delete('rbac-matrix.junit.xml');
      run.summary.suites = (run.summary.suites as { name: string }[]).filter((s) => s.name !== 'rbac-matrix');
    });
    const result = check(f, head);
    expect(result.status).toBe(1);
    expect(result.stdout).toContain('required suite rbac-matrix (security) missing');
  });

  it('[SEC-TC-48] FAIL on skipped > 0 in a security suite', () => {
    const { f, head } = withRun((run) => {
      run.files.set(
        'rbac-matrix.junit.xml',
        junitXml('rbac-matrix', [
          { name: '[SEC-TC-01] viewer cannot book', status: 'passed' },
          { name: 'owner can book', status: 'skipped' },
        ]),
      );
      Object.assign(suiteOf(run, 'rbac-matrix'), { tests: 2, skipped: 1 });
    });
    const result = check(f, head);
    expect(result.status).toBe(1);
    expect(result.stdout).toContain('zero-skip suite skipped 1');
  });

  it('[SEC-TC-48] FAIL on an untracked file in a code path of the checkout', () => {
    const { f, head } = withRun();
    write(f.root, 'apps/api/src/untracked.ts', 'export {};\n');
    const result = check(f, head);
    expect(result.status).toBe(1);
    expect(result.stdout).toContain('?? apps/api/src/untracked.ts');
  });

  it('[SEC-TC-48] FAIL when any SKIP_* variable is recorded', () => {
    const { f, head } = withRun((run) => {
      run.summary.env_overrides = ['SKIP_DOCKER_TESTS'];
    });
    const result = check(f, head);
    expect(result.status).toBe(1);
    expect(result.stdout).toContain('SKIP_DOCKER_TESTS');
  });

  it('[SEC-TC-48] FAIL on evidence older than a change to docs/03-architecture/api/openapi.yaml', () => {
    const { f } = withRun();
    write(f.root, 'docs/03-architecture/api/openapi.yaml', 'openapi: 3.1.1\n');
    const head = commitAll(f.root, 'docs(api): contract change');
    const result = check(f, head);
    expect(result.status).toBe(1);
    expect(result.stdout).toContain('stale');
    expect(result.stdout).toContain('docs/03-architecture/api/openapi.yaml');
  });

  it('[SEC-TC-48] FAIL on a missing required_cases ID (D-QA-004)', () => {
    const { f, head } = withRun((run) => {
      run.files.set('rbac-matrix.junit.xml', junitXml('rbac-matrix', [{ name: 'viewer cannot book', status: 'passed' }]));
      Object.assign(suiteOf(run, 'rbac-matrix'), { tests: 1 });
    });
    const result = check(f, head);
    expect(result.status).toBe(1);
    expect(result.stdout).toContain('required case SEC-TC-01 not in a passing test case');
  });

  it('[SEC-TC-48] FAIL on a JUnit file for a planned suite (D-QA-004)', () => {
    const { f, head } = withRun((run) => {
      run.files.set('e2e-chromium.junit.xml', junitXml('e2e-chromium', [{ name: 'home renders', status: 'passed' }]));
      (run.summary.suites as Record<string, unknown>[]).push({
        name: 'e2e-chromium',
        status: 'passed',
        tests: 1,
        failures: 0,
        errors: 0,
        skipped: 0,
        duration_s: 1,
        report: 'e2e-chromium.junit.xml',
        report_sha256: '',
      });
    });
    const result = check(f, head);
    expect(result.status).toBe(1);
    expect(result.stdout).toContain("still 'planned'");
  });

  it('[SEC-TC-48] a skipped test case carrying a SEC-TC ID fails in any suite', () => {
    const { f, head } = withRun((run) => {
      run.files.set(
        'unit.junit.xml',
        junitXml('unit', [
          { name: 'adds numbers', status: 'passed' },
          { name: '[SEC-TC-14] redacts', status: 'skipped' },
        ]),
      );
      Object.assign(suiteOf(run, 'unit'), { tests: 2, skipped: 1 });
    });
    const result = check(f, head);
    expect(result.status).toBe(1);
    expect(result.stdout).toContain('SEC-TC test case(s) skipped');
  });

  it('[SEC-TC-48] gate profile FAILs while a gate suite is planned and not deferred', () => {
    const { f, head } = withRun();
    const result = check(f, head, ['--profile', 'gate']);
    expect(result.status).toBe(1);
    expect(result.stdout).toContain('not active and not deferred: e2e-chromium');
  });
});

describe('check-evidence: R-ARCH-16 / R-ARCH-21 integrity', () => {
  it('[R-ARCH-16] a tampered attachment hash is rejected', () => {
    const { f, head } = withRun(undefined, (run) => {
      run.files.set('coverage-summary.json', '{"total":{"lines":{"pct":99}}}\n');
    });
    const result = check(f, head);
    expect(result.status).toBe(1);
    expect(result.stdout).toContain('SHA-256 mismatch for coverage-summary.json');
  });

  it('[R-ARCH-16] JUnit counts that differ from summary.json are rejected', () => {
    const { f, head } = withRun((run) => {
      Object.assign(suiteOf(run, 'unit'), { tests: 5 });
    });
    const result = check(f, head);
    expect(result.status).toBe(1);
    expect(result.stdout).toContain('unit tests 5 in summary.json but 1 in the JUnit');
  });

  it('[R-ARCH-16] a dirty tree (git_dirty true) is rejected', () => {
    const { f, head } = withRun((run) => {
      run.summary.git_dirty = true;
    });
    const result = check(f, head);
    expect(result.status).toBe(1);
    expect(result.stdout).toContain('git_dirty is true');
  });

  it('[R-ARCH-16] evidence whose git_sha is not an ancestor of the head is rejected', () => {
    const f = fixture();
    git(f.root, ['checkout', '-q', '-b', 'side', f.base]);
    write(f.root, 'apps/api/src/side.ts', 'export {};\n');
    const side = commitAll(f.root, 'feat: side');
    git(f.root, ['checkout', '-q', 'main']);
    writeRun(f.root, buildRun(side));
    const head = commitAll(f.root, 'test(evidence): side run');
    const result = check(f, head);
    expect(result.status).toBe(1);
    expect(result.stdout).toContain('is not an ancestor of the head');
  });

  it('[R-ARCH-21] a PASS without build_clean true is refused', () => {
    const { f, head } = withRun((run) => {
      run.summary.build_clean = false;
    });
    const result = check(f, head);
    expect(result.status).toBe(1);
    expect(result.stdout).toContain('build_clean is not true');
  });

  it('a file outside the run-directory allow-list (traces, HTML) is rejected', () => {
    const { f, head } = withRun((run) => {
      run.files.set('trace.zip', 'PK');
      (run.summary.attachments as { file: string; sha256: string }[]).push({ file: 'trace.zip', sha256: '' });
    });
    const result = check(f, head);
    expect(result.status).toBe(1);
    expect(result.stdout).toContain('not on the allow-list: trace.zip');
  });

  it('a schema-invalid summary.json is rejected', () => {
    const { f, head } = withRun((run) => {
      run.summary.lane = 'A';
    });
    const result = check(f, head);
    expect(result.status).toBe(1);
    expect(result.stdout).toContain('fails the schema');
  });
});

describe('check-evidence: CLI', () => {
  it('--report-only exits 0 on a failing check and says so', () => {
    const { f, head } = withRun((run) => {
      run.summary.git_dirty = true;
    });
    const result = check(f, head, ['--report-only']);
    expect(result.status).toBe(0);
    expect(result.stdout).toContain('FAIL (report-only)');
  });

  it('usage errors exit 2', () => {
    expect(runNode([script, '--base', 'HEAD'], { cwd: repoRoot }).status).toBe(2);
    expect(runNode([script, '--base', 'HEAD', '--head', 'HEAD', '--profile', 'nightly'], { cwd: repoRoot }).status).toBe(2);
  });

  it('allowedRunFile and nameHasId', () => {
    const manifest = parseManifest(MANIFEST);
    expect(allowedRunFile('unit.junit.xml', manifest)).toBe(true);
    expect(allowedRunFile('nope.junit.xml', manifest)).toBe(false);
    expect(allowedRunFile('k6-smoke.summary.json', manifest)).toBe(true);
    expect(allowedRunFile('lighthouse/home-en.json', manifest)).toBe(true);
    expect(allowedRunFile('report.html', manifest)).toBe(false);
    expect(nameHasId('[SEC-TC-14] x', 'SEC-TC-1')).toBe(false);
    expect(nameHasId('[SEC-TC-1] x', 'SEC-TC-1')).toBe(true);
  });
});
